package manifest

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/iwosmu/aghpen/lab/labcfg"
	"github.com/iwosmu/aghpen/lab/truth"
)

// File is one generated file.
type File struct {
	Path    string
	Content string
}

const (
	planBegin = "<!-- BEGIN ADDRESS PLAN (generated by lab/gen) -->"
	planEnd   = "<!-- END ADDRESS PLAN -->"
)

func jsonText(v any) (string, error) {
	var b strings.Builder
	enc := json.NewEncoder(&b)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(v); err != nil {
		return "", err
	}
	return b.String(), nil
}

// Files returns every generated file with its content. root is the lab directory.
func (l *Lab) Files(root string) ([]File, error) {
	var out []File
	add := func(rel, content string) { out = append(out, File{Path: filepath.Join(root, rel), Content: content}) }
	add("docker-compose.yml", l.Compose())
	add("generated/states.sh", l.StatesScript())
	for i := range l.Containers {
		c := &l.Containers[i]
		if cfg := c.SimConfig(); cfg != nil {
			txt, err := jsonText(cfg)
			if err != nil {
				return nil, err
			}
			add("labsim/hosts/"+c.Name+".json", txt)
		}
	}
	truths := map[string]*truth.File{}
	for _, st := range labcfg.States {
		truths[st] = l.Truth(st)
		txt, err := jsonText(truths[st])
		if err != nil {
			return nil, err
		}
		add("ground-truth/"+st+".json", txt)
	}
	for i := 0; i+1 < len(labcfg.States); i++ {
		from, to := labcfg.States[i], labcfg.States[i+1]
		cf := truth.ChangeFile{From: from, To: to,
			Note:    "Generated by lab/gen: the difference of the two ground-truth files. Unstable hosts are left out. Kinds follow model.ChangeKind.",
			Changes: truth.Diff(truths[from], truths[to])}
		txt, err := jsonText(cf)
		if err != nil {
			return nil, err
		}
		add(fmt.Sprintf("ground-truth/changes-%s-%s.json", from, to), txt)
	}
	// Target lists a scanner can load.
	var names []string
	for _, c := range l.Containers {
		if !c.NotAHost {
			names = append(names, c.FQDNs()...)
		}
	}
	add("ground-truth/targets-cidr.txt", Network+"\n")
	add("ground-truth/targets-domains.txt", strings.Join(uniq(names), "\n")+"\n")

	readme := filepath.Join(root, "README.md")
	if raw, err := os.ReadFile(readme); err == nil {
		s := string(raw)
		i, j := strings.Index(s, planBegin), strings.Index(s, planEnd)
		if i >= 0 && j > i {
			out = append(out, File{Path: readme, Content: s[:i+len(planBegin)] + "\n\n" + l.AddressPlan() + s[j:]})
		}
	}
	return out, nil
}

func uniq(in []string) []string {
	seen := map[string]bool{}
	var out []string
	for _, s := range in {
		if !seen[s] {
			seen[s] = true
			out = append(out, s)
		}
	}
	return out
}

// WriteFile writes one generated file, creating its directory.
func WriteFile(f File) error {
	if err := os.MkdirAll(filepath.Dir(f.Path), 0o755); err != nil {
		return err
	}
	return os.WriteFile(f.Path, []byte(f.Content), 0o644)
}
